chambre.reducer:
(
  $s := $state; $t := $action.type; $p := $action.payload;
  $cat := {"Lit simple": {"model": "lit"}, "Lit double": {"model": "lit", "params": {"largeur": 140}}, "Lit mezzanine": {"model": "lit", "params": {"type": "mezzanine"}}, "Lits superposés": {"model": "lit", "params": {"type": "superpose"}}, "Bureau": {"model": "bureau"}, "Chaise": {"model": "chaise"}, "Fauteuil": {"model": "fauteuil"}, "Canapé": {"model": "canape"}, "Pouf": {"model": "pouf"}, "Armoire": {"model": "armoire"}, "Commode": {"model": "commode"}, "Étagère murale": {"model": "etagere"}, "Table": {"model": "table", "params": {"largeur": 90, "profondeur": 60}}, "Tapis": {"model": "tapis"}, "Tapis rond": {"model": "tapis", "params": {"forme": "rond", "largeur": 140}}, "Coussin": {"model": "coussin"}, "Lampe de bureau": {"model": "lampe"}, "Lampadaire": {"model": "lampadaire"}, "Suspension": {"model": "suspension"}, "Applique": {"model": "applique"}, "Cadre": {"model": "cadre"}, "Miroir": {"model": "cadre", "params": {"miroir": true, "largeur": 50, "hauteur": 120}}, "Plante": {"model": "plante"}, "Rideau": {"model": "rideau"}};
  $t = "place" ? $merge([$s, {"monde": $mondePlace($s.monde, $p), "selection": $p.objectId, "src": $p.src}]) :
  $t = "select" ? $merge([$s, {"selection": $p.instance ? $p.instance : "", "src": $exists($p.src) ? $p.src : -1 }]) :
  $t = "add" ? (
    $e := $lookup($cat, $p);
    $e ? (
      $m := $mondeAdd($s.monde, $e);
      $merge([$s, {"monde": $m, "selection": $m.place[-1].name, "src": -1}])
    ) : $s
  ) :
  $t = "turn" ? ($s.selection ? $merge([$s, {"monde": $mondeTurn($s.monde, $s.selection, 90, $s.src)}]) : $s) :
  $t = "remove" ? ($s.selection ? (
    $m := $mondeRemove($s.monde, $s.selection, $s.src);
    /* un poster retiré emporte son image */
    $imgs := $m.images;
    $used := $append([], $m.place.params.image);
    $m := $type($imgs) = "object" ? $merge([$m, {"images": $merge($append([{}], $keys($imgs)[$ in $used].{$: $lookup($imgs, $)}))}]) : $m;
    $merge([$s, {"monde": $m, "selection": "", "src": -1}])
  ) : $s) :
  $t = "poster" and $type($p.image) = "string" ? (
    $imgs := $type($s.monde.images) = "object" ? $s.monde.images : {};
    $n := $count($keys($imgs));
    $n >= 6 ? $s : (
      $nom := "affiche" & ($max($append([0], $keys($imgs).$number($substringAfter($, "affiche")))) + 1);
      $h := 70;
      $l := $round(70 * $p.width / $p.height);
      $m := $mondeAdd($merge([$s.monde, {"images": $merge([$imgs, {$nom: $p.image}])}]), {"model": "poster", "params": {"image": $nom, "largeur": $l, "hauteur": $h, "baguette": "noire"}},
        /* vers le mur du fond (bord 0), celui qu'on voit en entrant */
        [$number($s.monde.espace.contour[1][0]) / 200, 0.3]);
      $merge([$s, {"monde": $m, "selection": $m.place[-1].name, "src": -1}])
    )
  ) :
  $t = "regle" and $s.selection and $type($p) = "string" ? (
    $typed := function($v) { $v = "true" ? true : $v = "false" ? false : $contains($v, /^-?[0-9.]+$/) ? $number($v) : $v };
    $kv := $contains($p, "=") ? (
      $i := $length($substringBefore($p, "="));
      {$substring($p, 0, $i): $typed($substring($p, $i + 1))}
    ) : (
      /* nombre : param;valeur;pas;min;max;sens */
      $q := $split($p, ";");
      $v := $number($q[1]) + $number($q[5]) * $number($q[2]);
      {$q[0]: $round($max([$number($q[3]), $min([$number($q[4]), $v])]), 4)}
    );
    $merge([$s, {"monde": $mondeParams($s.monde, $s.selection, $kv, $s.src)}])
  ) :
  $t = "reset" ? $merge([$s, {"monde": $merge([$s.monde, {"place": []}]), "selection": "", "src": -1}]) :
  $s
)

attributes.expression:
(
  $L := $number($input.largeur); $P := $number($input.profondeur); $H := $number($input.hauteur);
  $ma := $number($input.murAccent);
  /* motif choisi (« aucun » : couleur seule) */
  $tex := function($k, $c, $t, $a) { $type($k) = "string" and $k != "aucun" ? {"kind": $k, "color2": $c, "scale": $number($t), "angle": $number($a), "contrast": 0.8} : undefined };
  $mt := $tex($input.murMotif, $input.murMotifCouleur, $input.murMotifTaille, $input.murMotifAngle);
  $at := $tex($input.accentMotif, $input.accentMotifCouleur, $input.accentMotifTaille, $input.accentMotifAngle);
  $st := $tex($input.solMotif, $input.solMotifCouleur, $input.solMotifTaille, $input.solMotifAngle);
  {
    "contour": [[0, 0], [$L, 0], [$L, $P], [0, $P]],
    "hauteur": $H,
    "bords": [0, 1, 2, 3].(
      $b := $;
      $b = $ma
        ? $merge([{"bord": $b, "couleur": $input.accent}, $at ? {"tex": $at} : {}])
        : $merge([{"bord": $b, "couleur": $input.murs}, $mt ? {"tex": $mt} : {}])
    ),
    "zones": [$input.sol = "sur-mesure"
      ? $merge([{"nom": "plancher", "couleur": $input.solCouleur}, $st ? {"tex": $st} : {}])
      : {"nom": "plancher", "revetement": $input.sol}]
  }
)

(
  $i := $input.mondeInfo;
  $inst := $i.instances[name = $selection];
  $pf := $inst.prefab;
  $spec := $pf ? $lookup($i.prefabs, $pf).params : undefined;
  $e := $monde.place[name = $selection];
  $e := $e ? $e : ($src >= 0 ? $monde.place[$src] : undefined);
  $vals := $e.params;
  $LBL := {"type": "Type", "largeur": "Largeur", "longueur": "Longueur", "profondeur": "Profondeur", "hauteur": "Hauteur", "structure": "Bois / métal", "drap": "Drap", "couette": "Couette", "tete": "Tête de lit", "plateau": "Plateau", "pietement": "Pieds", "teinte": "Couleur", "caisson": "Caisson", "forme": "Forme", "pieds": "Pieds", "pose": "Pose", "niveaux": "Niveaux", "ecart": "Écart", "fond": "Fond", "portes": "Portes", "facade": "Façade", "tiroirs": "Tiroirs", "motif": "Motif", "taille": "Taille", "ouverture": "Ouverture", "tringle": "Tringle", "abat": "Abat-jour", "allume": "Allumé", "cadre": "Cadre", "image": "Image", "miroir": "Miroir", "pot": "Pot", "feuillage": "Feuillage", "teinte2": "Couleur du motif", "echelle": "Taille du motif", "angle": "Angle du motif", "baguette": "Baguette"};
  $PAL := [{"n": "Craie", "v": "#f4f1ea"}, {"n": "Lin", "v": "#e8dfcf"}, {"n": "Sable", "v": "#d9c39a"}, {"n": "Moutarde", "v": "#e0a458"}, {"n": "Corail", "v": "#e07a5f"}, {"n": "Framboise", "v": "#c9475b"}, {"n": "Lavande", "v": "#a99bd1"}, {"n": "Ciel", "v": "#7fa6c9"}, {"n": "Canard", "v": "#3d6b73"}, {"n": "Sauge", "v": "#8fae8b"}, {"n": "Forêt", "v": "#2e7d32"}, {"n": "Anthracite", "v": "#3b3f46"}, {"n": "Noir", "v": "#1f1f22"}, {"n": "Lumière chaude", "v": "#fff1c9"}, {"n": "Blanc cassé", "v": "#f1eee8"}, {"n": "Bleu nuit", "v": "#3d6b8c"}, {"n": "Brun", "v": "#2a2623"}, {"n": "Gris bleu", "v": "#c9d6df"}, {"n": "Terre cuite", "v": "#b5651d"}, {"n": "Ardoise", "v": "#1f2937"}, {"n": "Ocre", "v": "#d9d0c1"}];
  $MAT := ["chene", "pin", "noyer", "hetre", "bois-blanc", "bois-noir", "acier", "laiton", "metal-noir", "lin", "coton", "laine", "marbre", "pierre", "blanc", "noir"];
  $MATL := {"chene": "chêne", "pin": "pin", "noyer": "noyer", "hetre": "hêtre", "bois-blanc": "bois blanc", "bois-noir": "bois noir", "acier": "acier", "laiton": "laiton", "metal-noir": "métal noir", "lin": "lin", "coton": "coton", "laine": "laine", "marbre": "marbre", "pierre": "pierre", "blanc": "blanc", "noir": "noir"};
  $MOT := {"aucun": "Aucun", "rayures": "Rayures", "pois": "Pois", "damier": "Damier", "chevron": "Chevrons", "carrelage": "Carreaux", "brique": "Briques", "ecailles": "Écailles", "hachures": "Hachures", "tricot": "Tricot", "nuages": "Nuages", "marbre": "Marbre", "bois": "Bois", "beton": "Béton", "camouflage": "Camouflage", "tissu": "Tissu", "uni": "Uni"};
  $spec ? $append([], $each($spec, function($sp, $k) {
    (
      $v := $lookup($vals, $k);
      /* variables = proxys Concorde : une clé absente n'est pas undefined, on teste le type */
      $v := $type($v) in ["string", "number", "boolean"] ? $v : $sp.default;
      $kind := $sp.type = "nombre" and $exists($sp.options) ? "choix" : $sp.type = "matiere" ? "choix" : $sp.type;
      $opts := $sp.type = "matiere" ? $MAT : $sp.type = "couleur" ? $PAL.v : $sp.options;
      {
        "param": $k,
        "label": $exists($lookup($LBL, $k)) ? $lookup($LBL, $k) : $k,
        "type": $kind,
        "value": $string($v),
        "shown": $k = "motif" and $exists($lookup($MOT, $string($v))) ? $lookup($MOT, $string($v)) : $sp.type = "couleur" ? ($exists($PAL[v = $v]) ? $PAL[v = $v].n : $string($v)) : $sp.type = "matiere" ? $lookup($MATL, $v) : $sp.type = "bool" ? ($v ? "oui" : "non") : $string($v) & ($sp.unit ? " " & $sp.unit : ""),
        "min": $sp.min, "max": $sp.max, "step": $sp.step ? $sp.step : 1,
        "unit": $sp.unit ? $sp.unit : "",
        "options": $append([], $map($opts, function($o) {
          {"param": $k, "v": $string($o), "label": $sp.type = "couleur" ? $PAL[v = $o].n : $sp.type = "matiere" ? $lookup($MATL, $o) : $k = "motif" and $exists($lookup($MOT, $string($o))) ? $lookup($MOT, $string($o)) : $string($o) & ($sp.unit ? " " & $sp.unit : "")}
        }))
      }
    )
  }))[type != "texte"] : []
)

(
  /* valeurs Concorde : une liste absente n'est pas undefined, on ne garde que les vrais conflits */
  $all := $input.mondeInfo.conflicts;
  $c := $type($all) = "array" ? $append([], $all[$type(a) = "string"]) : [];
  $n := $count($c);
  $ty := $string($c[0].type); $a := $string($c[0].a); $b := $string($c[0].b);
  $txt := $ty = "chevauchement" ? $a & " touche " & $b
        : $ty = "degagement" ? $a & " gêne " & ($contains($b, "porte") ? "la porte" : "la fenêtre")
        : $ty = "hors-espace" ? $a & " sort de la pièce"
        : $a & " dépasse de " & $b;
  {"n": $n, "texte": $n = 0 ? "" : $txt & ($n > 1 ? " (et " & ($n - 1) & " autre" & ($n > 2 ? "s" : "") & ")" : "")}
)

(
  $f := $input;
  $tex := $type($f.motif) = "string" and $f.motif != "aucun" ? {"kind": $f.motif, "color2": $f.motifCouleur, "scale": 1.6, "contrast": 0.8} : undefined;
  $fo := $f.forme;
  $forme := $fo = "etoile" ? {"star": [5, 120, 52]}
    : $fo = "coeur" ? {"path": "M 0 70 C -150 -30 -80 -140 0 -60 C 80 -140 150 -30 0 70 Z"}
    : $fo = "cercle" ? {"circle": 100}
    : $fo = "soleil" ? {"star": [14, 120, 86]}
    : $fo = "eclair" ? {"poly": [[20, -130], [-60, 10], [-5, 10], [-25, 130], [60, -20], [5, -20]]}
    : $fo = "nuage" ? {"blob": [[-120, 30], [-100, -30], [-40, -60], [20, -80], [80, -40], [120, 10], [90, 50], [-60, 60]]}
    : undefined;
  $titre := $type($f.titre) = "string" ? $substring($trim($f.titre), 0, 40) : "";
  {"monde2d": {
    "ciel": $f.fond, "style": "plat", "outline": 0,
    "models": {"affiche": {"parts": $append($append(
      [$merge([{"name": "fond", "rect": [400, 500, 0], "color": $f.fond}, $tex ? {"tex": $tex} : {}])],
      $forme ? [$merge([{"name": "forme", "at": [0, 40], "color": $f.formeCouleur}, $forme])] : []),
      $titre != "" ? [{"name": "titre", "at": [0, -185], "text": {"text": $titre, "size": $length($titre) > 14 ? 30 : 46}, "color": $f.texteCouleur, "line": 0}] : [])}},
    "place": [{"model": "affiche", "name": "affiche", "at": [200, 250]}]
  }}
)
